                        {
                            resp = await _http.SendAsync(req, HttpCompletionOption.ResponseContentRead, cts.Token).ConfigureAwait(false);
                        }
                        catch (HttpRequestException) when (attempt < _maxRetries)
                        {
                            await BackoffAsync(attempt, cancellationToken).ConfigureAwait(false);
                            continue;
                        }
                        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
                        {
                            if (attempt < _maxRetries)
                            {
                                await BackoffAsync(attempt, cancellationToken).ConfigureAwait(false);
                                continue;
                            }
                            throw new TimeoutException($"{method} {url} timed out after {_timeout}");
                        }

                        using (resp)
                        {
                            var status = (int)resp.StatusCode;
                            if ((status == 429 || status == 502 || status == 503 || status == 504) && attempt < _maxRetries)
                            {
                                await BackoffAsync(attempt, cancellationToken).ConfigureAwait(false);
                                continue;
                            }
                            var text = resp.Content == null ? "" : await resp.Content.ReadAsStringAsync().ConfigureAwait(false);
                            if (status < 200 || status >= 300) throw new BappApiException(resp.StatusCode, text);
                            if (status == 204 || string.IsNullOrWhiteSpace(text)) return null;
                            return JsonNode.Parse(text);
                        }
                    }
                }
                finally
                {
                    foreach (var d in disposables) d.Dispose();
                }
            }
        }

        private async Task StreamUrlAsync(string url, Stream destination, CancellationToken cancellationToken)
        {
            using (var req = new HttpRequestMessage(HttpMethod.Get, url))
            using (var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken))
