                cts.CancelAfter(_timeout);
                using (var resp = await _http.SendAsync(req, HttpCompletionOption.ResponseHeadersRead, cts.Token).ConfigureAwait(false))
                {
                    if (!resp.IsSuccessStatusCode)
                    {
                        var text = await resp.Content.ReadAsStringAsync().ConfigureAwait(false);
                        throw new BappApiException(resp.StatusCode, text);
                    }
                    using (var s = await resp.Content.ReadAsStreamAsync().ConfigureAwait(false))
                    {
                        await s.CopyToAsync(destination, 81920, cancellationToken).ConfigureAwait(false);
                    }
                }
            }
        }

        private void ApplyHeaders(HttpRequestMessage req, IDictionary<string, string>? extra)
        {
            var headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (!string.IsNullOrEmpty(_userAgent)) headers["User-Agent"] = _userAgent!;
            if (_authHeader != null) headers["Authorization"] = _authHeader;
            if (!string.IsNullOrEmpty(Tenant)) headers["x-tenant-id"] = Tenant!;
            if (!string.IsNullOrEmpty(App)) headers["x-app-slug"] = App;
            if (extra != null)
                foreach (var kv in extra) headers[kv.Key] = kv.Value;
            foreach (var kv in headers)
                req.Headers.TryAddWithoutValidation(kv.Key, kv.Value);
        }

        private static HttpContent BuildContent(object body, List<IDisposable> disposables)
        {
            if (body is IDictionary<string, object?> dict && dict.Values.Any(v => v is BappFile))
            {
                var form = new MultipartFormDataContent();
                foreach (var kv in dict)
                {
                    if (kv.Value == null) continue;
                    HttpContent part;
                    string? fileName = null;
                    if (kv.Value is BappFile file)
                    {
                        part = file.ToContent(disposables);
                        fileName = file.Name;
                    }
                    else
                    {
                        part = new StringContent(FormValue(kv.Value), Encoding.UTF8);
                        part.Headers.ContentType = null;
                    }
                    part.Headers.ContentDisposition = Disposition(kv.Key, fileName);
                    form.Add(part);
                }
                return form;
            }

            string json = body is JsonNode node
                ? node.ToJsonString()
                : JsonSerializer.Serialize(body, body.GetType());
            return new StringContent(json, Encoding.UTF8, "application/json");
        }

        private static ContentDispositionHeaderValue Disposition(string name, string? fileName)
        {
            var cd = new ContentDispositionHeaderValue("form-data") { Name = Quote(name) };
            if (fileName != null)
            {
                var ascii = new string(fileName.Select(c => c < 128 && c != '"' && c != '\\' ? c : '_').ToArray());
                cd.FileName = Quote(ascii);
                if (ascii != fileName) cd.FileNameStar = fileName;
            }
            return cd;
        }

        private static string FormValue(object value)
        {
            switch (value)
            {
                case string s: return s;
                case bool b: return b ? "true" : "false";
                case DateTime dt: return dt.ToString("o", CultureInfo.InvariantCulture);
                case DateTimeOffset dto: return dto.ToString("o", CultureInfo.InvariantCulture);
                case JsonValue jv when jv.TryGetValue<string>(out var js): return js;
                case JsonNode n: return n.ToJsonString();
                case IFormattable f when !(value is Enum): return f.ToString(null, CultureInfo.InvariantCulture);
                case Enum e: return e.ToString();
                default:
                    return value is IEnumerable ? JsonSerializer.Serialize(value, value.GetType()) : value.ToString() ?? "";
            }
        }

        private static async Task BackoffAsync(int attempt, CancellationToken cancellationToken)
        {
            double jitter;
            lock (Jitter) jitter = Jitter.NextDouble();
            var seconds = Math.Min(Math.Pow(2, attempt) + jitter, 10);
            await Task.Delay(TimeSpan.FromSeconds(seconds), cancellationToken).ConfigureAwait(false);
        }

