        private static PagedList ToPagedList(JsonNode? node)
        {
            var results = new List<JsonObject>();
            if (node is JsonArray bare)
            {
                results.AddRange(bare.OfType<JsonObject>());
                return new PagedList(results, results.Count, null, null);
            }
            var obj = node as JsonObject;
            if (obj?["results"] is JsonArray arr) results.AddRange(arr.OfType<JsonObject>());
            var count = obj?["count"] is JsonValue cv && cv.TryGetValue<int>(out var c) ? c : results.Count;
            return new PagedList(results, count, Str(obj?["next"]), Str(obj?["previous"]));
        }

